{"cards": [{"node_code": "N_2165be3e0e2c54f2", "definition": "研究沥青路面各结构层厚度、材料参数及组合方式的计算理论与设计方法，旨在满足承载能力、抗变形及抗疲劳等性能指标。", "boundary": "本节点聚焦于设计阶段的定量计算与方案确定。边界在于区分“设计计算”与“材料性能研究”或“结构形式描述”：具体的沥青混合料级配优化归入性能或材料相关节点，层间组合逻辑归入结构组合节点；本节点核心是依据荷载与环境作用，通过力学模型（如弹性层状体系）确定各层厚度与模量。不包含施工工艺流程或建成后的检测评价。", "includes": ["基于弹性层状体系理论的路面厚度计算方法", "沥青路面结构层的模量取值、当量换算及设计参数确定", "满足抗车辙、抗疲劳、抗冻裂等指标的结构方案优化"], "excludes": ["沥青混合料本身的级配设计、配合比设计及材料微观性能研究", "路面结构层的物理构造形式描述（如层位划分原则，归入路面结构组合）"], "sibling_distinctions": [{"other_code": "N_783b33c89b6fcd2e", "rule": "本节点侧重“算”（厚度、模量计算），兄弟节点侧重“构”（层位划分、材料类型选择及组合逻辑）。"}, {"other_code": "N_bdcb15e2180b311d", "rule": "本节点利用性能指标作为设计约束条件，兄弟节点侧重性能指标本身的定义、测试方法及材料本构关系研究。"}, {"other_code": "N_f806a0f215437e3f", "rule": "本节点将作用（荷载、温度）作为设计输入参数进行计算，兄弟节点侧重作用本身的分析、分布规律及环境效应机理。"}], "cross_boundary_rule": "当涉及设计参数对性能的影响分析时，若重点在于确定厚度/模量以满足指标，归入本节点；若重点在于揭示材料/结构对特定性能指标的响应机理，归入性能节点。"}, {"node_code": "N_f806a0f215437e3f", "definition": "研究作用于沥青路面的交通荷载、温度场、湿度及环境因素的分析方法，及其在路面结构中的分布规律与效应。", "boundary": "本节点聚焦于设计输入端的“作用”分析。边界在于区分“作用分析”与“结构响应”：本节点关注荷载如何传递、温度梯度如何形成、水分如何侵入等外部或内部环境/荷载状态；结构层在作用下的应力应变计算归入结构设计节点。不包含车辆动力学或纯气象学研究，仅关注其对路面结构的影响机制。", "includes": ["轴载当量换算、荷载分布及轮迹作用分析", "路面温度场分布、温度梯度及温度应力分析", "水分侵入、冻融循环等环境作用对路面结构的影响机制"], "excludes": ["路面结构在荷载/温度作用下的应力、应变及变形计算（归入结构设计）", "车辆行驶稳定性或交通流理论（归入交通工程其他分支）"], "sibling_distinctions": [{"other_code": "N_2165be3e0e2c54f2", "rule": "本节点提供设计所需的荷载与环境参数（输入），兄弟节点利用这些参数进行结构厚度与模量计算（处理）。"}, {"other_code": "N_bdcb15e2180b311d", "rule": "本节点关注外部作用（如温度、荷载）的分布与效应，兄弟节点关注结构/材料在作用下的内在性能表现（如抗车辙能力）。"}], "cross_boundary_rule": "当研究温度对沥青混合料性能的影响时，若侧重温度场分布及温度应力产生，归入本节点；若侧重不同温度下混合料模量变化规律，归入性能节点。"}]}
